export const cardEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=cardEscape;
function safePhoto(url){return typeof url==='string'&&(/^(https?:\/\/|\/|assets\/)/.test(url)||/^data:image\/(png|jpeg|webp);base64,/.test(url))?url:null;}
export function debtCardHTML(card,{saved=false,sample=false,id=''}={}){const photo=safePhoto(card.photo);return `<article class="debt-face"><div class="debt-face-art ${photo?'has-photo':''}">${photo?`<img src="${e(photo)}" alt="Ảnh đại diện của ${e(card.name)}">`:'<div class="df-sun"></div><div class="df-hill"></div><div class="df-hill second"></div><div class="df-heart">♡</div>'}${sample?'<span class="df-sample">Hồ sơ mẫu</span>':''}</div><div class="df-body"><div class="df-person"><h2>${e(card.name)}${card.age?`<span>, ${e(card.age)}</span>`:''}</h2>${card.location?`<p>⌖ ${e(card.location)}</p>`:''}</div><div class="df-titles">${card.debts.map((d,index)=>`<div><span>${String(index+1).padStart(2,'0')}</span><h3>${e(d.title)}</h3>${Number.isSafeInteger(d.amount)?`<strong class="df-amount">${new Intl.NumberFormat('vi-VN').format(d.amount)} ₫</strong>`:''}</div>`).join('')}</div><div class="df-bottom"><p>Tap the app logo to learn more about this card.</p><div class="df-actions"><button class="df-skip" data-dc="skip" data-id="${e(id)}" aria-label="Bỏ qua thẻ"><b>×</b><span>Bỏ qua</span></button><button class="df-save ${saved?'is-saved':''}" data-dc="save" data-id="${e(id)}" aria-label="${saved?'Bỏ lưu thẻ':'Lưu thẻ'}" aria-pressed="${saved}"><b>${saved?'★':'☆'}</b><span>${saved?'Saved':'Save'}</span></button><button class="df-learn" data-dc="detail" data-id="${e(id)}" aria-label="Xem thêm thông tin chi tiết"><span class="df-logo-icon"><img src="assets/debtfreelately-mark-clean.png" alt="Logo DebtFreeLately"></span><span>Chi tiết</span></button></div></div></div></article>`;}
export function cardDetailsHTML(card){return `<div class="eyebrow">DEBT CARD · THÔNG TIN HIỂN THỊ</div><h2>${e(card.name)}${card.age?`, ${e(card.age)} tuổi`:''}</h2>${card.location?`<p>⌖ ${e(card.location)}</p>`:''}${card.debts.map(d=>`<h3>${e(d.title)}</h3><p class="detail-story">${d.story?e(d.story):'Người đăng đang giữ riêng tư câu chuyện của khoản nợ này.'}</p>`).join('')}`;}
